// Ambient declarations for asset imports that TS doesn't know about.
// expo-env.d.ts is auto-generated by Expo and must not be edited — keep
// project-specific declarations here instead.

declare module '*.css';

declare module '*.module.css' {
  const classes: { readonly [key: string]: string };
  export default classes;
}

// expo-image SDK 56 ships without a built `build/` folder in some
// installs, so TS can't resolve its types. The runtime still works
// (Metro reads from `src/`). Shim until we hit a version with proper
// type distribution.
declare module 'expo-image';
